def max_aggregate(stdata):
    """Write a function to calculate the maximum aggregate from the list of tuples.

    Aggregate (sum) the values for each name in ``stdata`` and return a
    ``(name, total)`` tuple for the name with the largest total. If several
    names share the largest total, the one encountered first is returned.
    Like ``max``, this raises ``ValueError`` for an empty input.
    """
    totals = {}
    for name, value in stdata:
        totals[name] = totals.get(name, 0) + value
    return max(totals.items(), key=lambda item: item[1])
